    def wait_for_infomodel_event(self, event, timeout=60, alias='default'):
        """Wait for specific InfoModel event

        :param string event: expected InfoModel event description.
        :param float timeout: Time to wait for event occuerence (by default in seconds).
        :param string alias: Name of execution context.

        :rtype: string (Latest event occurence timestamp or None if zero occurences expected)
        :raises: InfoModelTimeoutException when *event* didnt occur expected number of times within *timeout* seconds


        **EVENT DESCRIPTION:**

        +------------+-----------+-------------------------------------------------------------------------+
        | TYPE       | SYNTAX + EXAMPLE                                                                    |
        +============+===========+========================================+================================+
        | **reset**  | **reset [times CONDITION]**                                                         |
        |            +-----------+----------------------------------------+--------------------------------+
        |            | Examples: | reset                                  | at least one reset             |
        |            |           +----------------------------------------+--------------------------------+
        |            |           | reset times=2                          | exactly 2 resets               |
        +------------+-----------+----------------------------------------+--------------------------------+
        | **remove** | **remove DIST_NAME [PARAMETER_VALUE] [times CONDITION]**                            |
        |            +-----------+----------------------------------------+--------------------------------+
        |            | Example:  | remove /A-1/B-* times<3                | remove any B class object      |
        |            |           |                                        | under /A-1 less than 3 times   |
        |            |           +----------------------------------------+--------------------------------+
        |            |           | remove /A-1/B-1 [param=value]          | remove /A-1/B-1 object         |
        |            |           |                                        | with defined param value       |
        +------------+-----------+----------------------------------------+--------------------------------+
        | **create** | **create DIST_NAME [PARAMETER_VALUE] [times CONDITION]**                            |
        |            +-----------+----------------------------------------+--------------------------------+
        |            | Example:  | create /A-1/B-* times>2                | create any B class object      |
        |            |           |                                        | under /A-1 more than 2 times   |
        |            |           +----------------------------------------+--------------------------------+
        |            |           | create /A-1/B-1 [param=value]          | create /A-1/B-1 object         |
        |            |           |                                        | with defined param value       |
        +------------+-----------+----------------------------------------+--------------------------------+
        | **change** | **change DIST_NAME [PARAMETER_CHANGE] [times CONDITION]**                           |
        |            +-----------+----------------------------------------+--------------------------------+
        |            | Examples: | change /A-1/B-1/C-1 times>=2           | change of /A-1/B-1/C-1 object  |
        |            |           |                                        | params twice or more           |
        |            |           +----------------------------------------+--------------------------------+
        |            |           | change /A-1/B-1/C-* [param]            | change of /A-1/B-1/C-* param   |
        |            |           |                                        |                                |
        |            |           +----------------------------------------+--------------------------------+
        |            |           | change /A-1/B-1/C-1 [param: x ->  y]   | change /A-1/B-1/C-1 param      |
        |            |           |                                        | value from x to y              |
        |            |           +----------------------------------------+--------------------------------+
        |            |           | change /A-1/B-1/C-1 [param: * ->  x]   | change /A-1/B-1/C-1 param      |
        |            |           |                                        | from any value to x            |
        |            |           +----------------------------------------+--------------------------------+
        |            |           | change /A-1/B-1/C-1 [param: x -> !x]   | change /A-1/B-1/C-1 param      |
        |            |           |                                        | from x to not x                |
        +------------+-----------+----------------------------------------+--------------------------------+
        | **update** | **[update] DIST_NAME [PARAMETER_CHANGE]**                                           |
        |            +-----------+----------------------------------------+--------------------------------+
        |            | Examples: | update /A-1/B-*                        | any update of /A-1/B-* objects |
        |            |           |                                        | including creation, remove     |
        |            |           |                                        | and reset                      |
        |            |           +----------------------------------------+--------------------------------+
        |            |           | /A-1/B-1 [param: empty -> x]           | update of /A-1/B-1 param form  |
        |            |           |                                        | empty value to x (including    |
        |            |           |                                        | creation)                      |
        +------------+-----------+----------------------------------------+--------------------------------+


        **DIST_NAME syntax:**
            * same as Query InfoModel dist name syntax

        **PARAMETER_VALUE syntax**
            - [PARAMETER1 OPERATOR VALUE]
                * examples: [param>5], [temperature = 100], [status=empty]
                * square brackets are obligatory
                * single spaces between elements are allowed with one exception - VALUE empty

        **PARAMETER_CHANGE syntax**
            - [PARAMETER: OPERATOR1 VALUE1 -> OPERATOR2 VALUE2]
                * examples: [param], [param: value1 -> value2], [param: empty -> !value]
                * predicate with param name only matches any change of this param

        ** PARAMETER syntax**
            - simple: temperature, status, etc.
            - nested: stateInfo.availabilityStatus, etc.
            - list: alarms[5]

        ** OPERATORs syntax**
            - examples: >, <, >=, <=, =, !=, !
            - empty operator is interpreted as '='

        ** VALUE syntax**
            - *: any value (including empty)
            - numeric: 5, 11.0
            - literal: disabled, OnAir, etc.
            - quoted: "disabled", "OnAir", etc.
            - regex: regex"[0-9]+", regex"[Oo]nline"
            - empty: string 'empty' is interpreted as an empty value
            - not-empty: string 'not-empty' is interpreted as not empty value

        **CONDITION syntax:**
            - times OPERATOR VALUE, e.g. times>2
            - OPERATOR is one of: =, >, <, >=, <=, !=
            - VALUE is an integer number
            - empty condition is intepreted as times>=1 (expected at least one occurence)
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(event)
        IsNumber().check(timeout)
        IsString().check(alias)
        return self.store.get(alias).wait_for_event(event, timeout)

    def initialize_ims2_validator(self, filename, alias='default'):
        """Initialize IMS2 validator. Open IMS2 file for validation.

        :param string filename: Path to InfoModel log file to be validated.
        :param string alias: Name of execution context.

        :note: Setup not required.
        """
        IsString().check(filename)
        return InfoModel.initialize_ims2_validator(filename)

    def add_expected_ims2_event(self, event, alias='default'):
        """Add expected InfoModel event for IMS2 validation.

        :param string event: InfoModel event description.
        :param string alias: Name of execution context.

        :note: Setup not required.
        """
        IsString().check(event)
        return InfoModel.add_expected_ims2_event(event)

    def add_expected_ims2_event_sequence(self, alias='default', **kw):
        """Add expected InfoModel event sequence for IMS2 validation.

        :param string alias: Name of execution context.

        :note: Setup not required.
        """
        return InfoModel.add_expected_ims2_event_sequence(events=kw)

    def validate_ims2(self, alias='default'):
        """Perform IMS2 validatotion. Keyword will check if all expected events occured in given InfoModel log.

        :param string alias: Name of execution context.

        :note: Setup not required.
        """
        IsString().check(alias)
        return InfoModel.validate_ims2()

    def get_change_sets(self, filename, event, alias='default'):
        """Get change sets. Read IMS2 file and return change sets matching given event description.

        :param string filename: InfoModel log file to read.
        :param string event: InfoModel event description.

        :note: Setup not required.
        """
        IsString().check(filename)
        IsString().check(event)
        return InfoModel.get_change_sets(filename, event)

    def get_multiple_change_sets(self, filename, alias='default', **kw):
        """Get change sets. Read IMS2 file and return change sets matching given event description.

        :param string filename: Infomodel log file to read.

        :note: Setup not required.
        """
        IsString().check(filename)
        return InfoModel.get_multiple_change_sets(filename, events=kw)
